import{z as l,x as n,o as A,c as p,q as s,j as B,D as e,d as t,s as o,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"帧与 MAC","description":"","frontmatter":{"title":"帧与 MAC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/frame-mac.md","filePath":"cs/frame-mac.md","lastUpdated":1791413859000}'),d={name:"cs/frame-mac.md"};function C(m,a,c,M,f,h){const E=n("Mermaid");return A(),p("div",null,[a[2]||(a[2]=s('<h1 id="帧与-mac" tabindex="-1">帧与 MAC <a class="header-anchor" href="#帧与-mac" aria-label="Permalink to &quot;帧与 MAC&quot;">​</a></h1><div class="epigraph"><p>链路上传送的是帧：目的与源的硬件地址、类型、载荷与校验；MAC 决定谁在何时占用介质。</p><footer>—— 据 Metcalfe and Boggs, Ethernet: Distributed Packet Switching for Local Computer Networks, CACM 1976；IEEE 802 整理</footer></div><p><a href="/cs/five-vs-four-layer">上一课</a>给出分层与端到端，还没有一跳的 PDU。<a href="/cs/io-dma">I/O 与 DMA</a> 能把网卡缓冲搬进内存，但缓冲里的位如何被邻机认成「给我的」。缺口是<strong>帧</strong>与 <strong>MAC 地址</strong>：链路层的名字，只在这一跳有效。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>广播介质上，所有网卡都可能看见电信号。若没有目的地址，每台主机都要把噪声当数据。以太网风格：48 位 MAC、帧头、载荷（后课的 IP 包放这里）、FCS。网卡用 DMA 收齐一帧，用地址过滤：不是自己且不是广播/组播则丢。缺口不是 IP 路由，而是这一跳的命名与成帧。</p><p><span class="marginnote">可以把它想象成小区门牌与通信地址的关系：MAC 是接口出厂刻好的「门牌号」，只在这栋楼（本跳网段）里被认；包裹要寄到另一个城市，靠的是 IP 这个「通信地址」，而且每过一跳还要换一次门牌。</span></p><p>本课不把 CSMA 退避算法写完，那是后面 <a href="/cs/csma-switch">CSMA 与交换</a>一课的事。</p><p><span class="marginnote">MAC 地址由厂商与全局/本地位组成，链路层当扁平标识用。它不是地理位置，也不能代替 IP 的跨网编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送：上层交出载荷，驱动加上目的/源 MAC 与以太类型，算 FCS，经 DMA 出门。接收：FCS 错则丢（链路努力，不是端到端保证）；类型字段交给 IP 或其他。点到点链路（PPP）帧格式不同，对象仍是「一跳 PDU + 校验」。</p><p><span class="marginnote">以太类型（EtherType）就是帧头里的「下一步交给谁」指示牌：0x0800 表示载荷是 IPv4 包，0x86DD 是 IPv6，0x0806 是 ARP——网卡收齐一帧后照着它把载荷递给对应的上层协议。</span></p>',11)),(A(),B(i,null,{default:e(()=>[o(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAY%5B%22%E7%BD%91%E7%BB%9C%E5%B1%82%E8%BD%BD%E8%8D%B7%22%5D%20--%3E%20FR%5B%22%E5%8A%A0%20MAC%20%E5%A4%B4%E4%B8%8E%20FCS%22%5D%0A%20%20FR%20--%3E%20WIRE%5B%22%E4%BB%8B%E8%B4%A8%22%5D%0A%20%20WIRE%20--%3E%20FILT%5B%22%E7%9B%AE%E7%9A%84%E8%BF%87%E6%BB%A4%22%5D%0A%20%20FILT%20--%3E%20UP%5B%22%E4%BA%A4%E7%BB%99%E7%B1%BB%E5%9E%8B%E5%AF%B9%E5%BA%94%E7%9A%84%E4%B8%8A%E5%B1%82%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"帧把「邻机」从物理连通变成可寻址。交换机（后面 CSMA 与交换一课）正是学这些地址来转发；路由器则剥到 IP 再决定下一跳，可能换一个全新的 MAC。端到端论证：FCS 只覆盖这一跳，中间任何存储转发节点之后仍要上层校验。",-1)),(A(),B(i,null,{default:e(()=>[o(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%BB%E6%9C%BA%20A%20%E5%8F%91%E5%B8%A7%22%5D%20--%3E%20SW%5B%22%E4%BA%A4%E6%8D%A2%E6%9C%BA%E6%8C%89%E7%9B%AE%E7%9A%84%20MAC%20%E8%BD%AC%E5%8F%91%22%5D%0A%20%20SW%20--%3E%20RT%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%EF%BC%9A%E5%89%A5%E5%B8%A7%E6%9F%A5%20IP%20%E8%B7%AF%E7%94%B1%22%5D%0A%20%20RT%20--%3E%20REW%5B%22%E9%87%8D%E6%96%B0%E6%88%90%E5%B8%A7%EF%BC%9A%E6%8D%A2%E4%B8%8A%E6%9C%AC%E6%AE%B5%E6%96%B0%20MAC%22%5D%0A%20%20REW%20--%3E%20SW2%5B%22%E4%B8%8B%E4%B8%80%E8%B7%B3%E4%BA%A4%E6%8D%A2%E6%9C%BA%22%5D%0A%20%20SW2%20--%3E%20B%5B%22%E4%B8%BB%E6%9C%BA%20B%20%E6%94%B6%E5%B8%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">这张图回答「MAC 地址跨网时去哪了」：初学者容易以为两台隔互联网的机器通信时帧头不变——实际上每经过一个路由器，源/目的 MAC 都被换成本段链路上的新值；端到端不变的是 IP 地址，不是 MAC。</span></p><p>与进程无关：MAC 命名的是接口，不是<a href="/cs/file-bytestream">文件描述符</a>。进程要等到套接字课才接到传输层端口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Wi-Fi 的关联与 802.11 帧都展开，不引入 VLAN 标签的全部 802.1Q 细节。也不把 MAC 随机化隐私策略写成安全课。冲突如何在共享介质上检测与退避，以及如何在交换式全双工里消失，都在后面 CSMA 与交换一课。</p><p>巨帧与标准 MTU 是接口配置；IP 层的 MTU 发现依赖链路实际能装多少载荷。本课不把巨型帧当默认。</p><p>后课默认：一跳靠 MAC 与帧。共享总线如何避免同时发送，以及交换如何学地址，在后面 CSMA 与交换一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>帧是链路 PDU；MAC 是接口的扁平地址。</li><li>FCS 是一跳努力，代替不了端到端。</li><li>冲突与交换在后面 CSMA 与交换一课。</li><li>出处：Metcalfe and Boggs, <em>CACM</em> 1976；IEEE 802.3；Kurose and Ross。</li></ul>',8))])}const u=l(d,[["render",C]]);export{P as __pageData,u as default};
